mask = {(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# shapes square plus L orientations with missing corner colors
orient={2:{(0,1),(1,0),(1,1)},3:{(0,0),(0,1),(1,1)},4:{(0,0),(1,0),(1,1)},5:{(0,0),(0,1),(1,0)}}
placements=[]
for col,sh in orient.items():
 for r in range(6):
  for c in range(6):
   cells={(r+dr,c+dc) for dr,dc in sh}
   if cells<=mask:placements.append((col,cells))
for r in range(6):
 for c in range(6):
  cells={(r+dr,c+dc) for dr,dc in {(0,0),(0,1),(1,0),(1,1)}}
  if cells<=mask:placements.append((1,cells))
solutions=[]
def rec(rem,chosen):
 if not rem:
  if len(chosen)==5 and sum(1 for x in chosen if x[0]==1)==1: solutions.append(chosen)
  return
 cell=min(rem)
 for col,cells in placements:
  if cell in cells and cells<=rem:
   rec(rem-cells,chosen+[(col,cells)])
rec(mask,[])
len(solutions)
